import { Table, ReferenceColumn, BooleanColumn, StringColumn, UserRolesColumn, TranslatedFieldColumn } from '../../db'

export const sys_ui_view = Table({
    name: 'sys_ui_view',
    extends: 'sys_metadata',
    schema: {
        group: ReferenceColumn({
            mandatory: false,
            label: 'Group',
            read_only: false,
            active: true,
            maxLength: 32,
            referenceTable: 'sys_user_group',
        }),
        hidden: BooleanColumn({
            mandatory: false,
            label: 'Hidden',
            read_only: false,
            active: true,
            default: false,
            maxLength: 40,
        }),
        name: StringColumn({
            mandatory: false,
            label: 'Name',
            read_only: false,
            active: true,
            maxLength: 80,
            dropdown: 'none',
        }),
        roles: UserRolesColumn({ mandatory: false, label: 'Roles', read_only: false, active: true, maxLength: 100 }),
        title: TranslatedFieldColumn({
            mandatory: false,
            label: 'Title',
            read_only: false,
            active: true,
            maxLength: 80,
        }),
        user: ReferenceColumn({
            mandatory: false,
            label: 'User',
            read_only: false,
            active: true,
            maxLength: 32,
            referenceTable: 'sys_user',
        }),
    },
})
